    /* 로그아웃 */
    onBtnLogoutTap: function(button, e, eOpts) {
        var me = this;

        Ext.Msg.confirm(Property.SYSTEM_NAME, '로그아웃하시겠습니까?', function(choice) {
            var me = this;
            if (choice === 'yes') {
                Ext.Ajax.request({
                    headers: {
                        viewId: me.getViewId(),
                        serviceId: 'COMAPP0002R02M'
                    },
                    scope : me,
                    success : function(res) {
                        if (Property.IS_DEBUG) console.log('로그아웃 성공');
                    },
                    failure: function(response, opts) {
                        if (Property.IS_DEBUG) console.log('로그아웃 실패');
                    }
                });

                // 토큰정보 삭제
                localStorage.removeItem(Property.JWT_TOKEN_NAME);
                WebUtils.setCookie(Property.JWT_TOKEN_NAME, null, -1);

                // 로그인화면으로 이동
                me.REDIRECT('LoginV1');

                var homes = Ext.ComponentQuery.query('#' + Property.ROUTE_HOME);
                if (homes.length !== 0) {
                    homes[0].destroy();
                }
            }
        }, me);
    },

    onMytreelistItemClick: function(sender, info, eOpts) {
        var me = this;

        if (info.select) {
            // 사우회앱 스키마콜
            if (info.node.data.menuId == 'bfslink') {
                var ios_scheme = 'bfslink://action',						// 사우회엡 스키마
                android_scheme = 'kr.co.bnksys.bfs',					// 사우회앱 안드로이드 패키지
                url = 'https://bfs.bnksys.co.kr/app/distribution.html',	// 사우회앱 다운로드 url
                scheme = '',
                jwtToken = localStorage.getItem(Property.JWT_TOKEN_NAME),
                principal = SecurityUtils.getPrincipal(),
                params = '?TOKEN=' + jwtToken + '&PARAM=';
                var jsonData = '{' +
                    'cmgrp_cd : \"' + principal.cmgrpCd + '\", ' +
                    'cmgrp_id : \"' + principal.cmgrpId + '", ' +
                    'comp_emladr : \"' + principal.compEmladr + '\", ' +
                    'dpnm : \"' + principal.dpnm + '\", ' +
                    'empe_psit_cd : \"' + principal.empePsitCd + '\", ' +
                    'empe_psit_nm : \"' + principal.empePsitNm + '\", ' +
                    'etco_dt : \"' + principal.etcoDt + '\", ' +
                    'hr_hrpm_dept_id : \"' + principal.hrHrpmDeptId + '\", ' +
                    'user_id : \"' + principal.userId + '\", ' +
                    'user_nm : \"' + principal.userNm + '\"' +
                '}';

                params = params + jsonData + '&SECRET=BNK_' + principal.sysCd;

                if (Ext.os.is.Android) {
                    scheme = android_scheme;
                } else {
                    scheme = ios_scheme;
                }

                appAvailability.check(
                scheme,
                function() {
                    ios_scheme = ios_scheme + params;
                    window.open(ios_scheme, '_system');
                },
                function() {
                    window.open(url, '_system');
                }
                );
            } else {
                // me.toggleMenu(0);
                var title = info.node.data.text;
                //         me.showView(info.node.data.menuId , info.node.data.text);
                me.showView(info.node.data.menuId , title.replace('- ', ''));
            }
        }
    },

